mapper.select:
SELECT id, username, email, real_name AS realName, CASE status WHEN 0 THEN 'DEACTIVATED' WHEN 1 THEN 'ACTIVE' WHEN 2 THEN 'SECURITY_SUSPENDED' END AS status, created_at AS createdAt, updated_at AS updatedAt FROM t_user WHERE deleted_at IS NULL
AND status = #{criteria.status}
AND ( POSITION(lower(#{criteria.searchTerm}) IN lower(username)) > 0 OR POSITION(lower(#{criteria.searchTerm}) IN lower(COALESCE(email, ''))) > 0 OR POSITION(lower(#{criteria.searchTerm}) IN lower(COALESCE(real_name, ''))) > 0 )
AND (created_at, id) < (#{criteria.cursorCreatedAt}, #{criteria.cursorId})
ORDER BY created_at DESC, id DESC LIMIT #{criteria.fetchSize}
